(()=>{
const search=document.getElementById('travelCountrySearch'),list=document.getElementById('travelCountryList'),count=document.getElementById('travelCountryCount'),clear=document.getElementById('clearTravelCountrySearch'),brief=document.getElementById('travelHealthBrief');if(!search||!list||!brief)return;
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const aliases={'Cabo Verde':'Cape Verde','Congo, Democratic Republic':'DR Congo','Congo, Republic':'Congo','Côte d’Ivoire':'Ivory Coast'};
const adviceSlugs={'Côte d’Ivoire':'ivory-coast','Congo, Democratic Republic':'democratic-republic-of-the-congo','Congo, Republic':'republic-of-the-congo','São Tomé and Príncipe':'sao-tome-and-principe','Eswatini':'eswatini','Gambia':'the-gambia'};
const cdcSlugs={'Cabo Verde':'cape-verde','Côte d’Ivoire':'cote-divoire','Congo, Democratic Republic':'democratic-republic-of-the-congo','Congo, Republic':'republic-of-the-congo','Gambia':'the-gambia','São Tomé and Príncipe':'sao-tome-and-principe'};
const countries=(window.africanAtlas||[]).map(([name,region])=>({name,region}));let selected='';let request=0;
const slug=name=>adviceSlugs[name]||name.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/&/g,'and').replace(/[^a-z0-9]+/g,'-').replace(/(^-|-$)/g,'');
function renderList(){const q=search.value.trim().toLowerCase(),rows=countries.filter(x=>x.name.toLowerCase().includes(q));count.textContent=`${rows.length} ${rows.length===1?'country':'countries'}`;clear.hidden=!q;list.innerHTML=rows.length?rows.map(x=>`<button type="button" class="${x.name===selected?'selected':''}" data-travel-country="${esc(x.name)}"><strong>${esc(x.name)}</strong><span>${esc(x.region)}</span></button>`).join(''):'<p class="travel-country-no-results">No country matches this search.</p>'}
function officialLinks(country,data){const code=String(data?.cca2||'').toLowerCase(),gov=slug(country),cdc=cdcSlugs[country]||slug(country);return {gov:`https://www.gov.uk/foreign-travel-advice/${gov}`,entry:`https://www.gov.uk/foreign-travel-advice/${gov}/entry-requirements`,who:code?`https://www.who.int/countries/${code}/`:'https://www.who.int/countries/',cdc:`https://wwwnc.cdc.gov/travel/destinations/traveler/none/${cdc}`}}
function staticPanels(country,data,links){return `<section class="travel-panel"><p class="eyebrow dark">VACCINATIONS &amp; MALARIA</p><h3>Check recommendations for your exact itinerary</h3><p>Vaccine recommendations, entry certificates and malaria prevention can differ by area, season, trip type and traveller. Review the current country guidance and speak to a qualified travel-health professional before departure.</p><div class="travel-health-note"><strong>About malaria prevention</strong><p>There is no single routine “malaria shot” for travellers. Depending on current guidance, prevention can include avoiding bites and prescription medicine. Use the official country guidance below for the latest advice.</p></div><div class="travel-links"><a href="${links.cdc}" target="_blank" rel="noopener">CDC traveller view ↗</a><a href="${links.who}" target="_blank" rel="noopener">WHO ${esc(country)} profile ↗</a></div></section><section class="travel-panel"><p class="eyebrow dark">OUTBREAKS &amp; PUBLIC HEALTH</p><h3>Review current notices</h3><p>Outbreak information changes and is not stored as a permanent country claim in the Pocketbook.</p><div class="travel-links"><a href="https://www.who.int/emergencies/disease-outbreak-news" target="_blank" rel="noopener">WHO outbreak news ↗</a><a href="https://africacdc.org/disease-outbreak/" target="_blank" rel="noopener">Africa CDC outbreaks ↗</a></div></section><section class="travel-panel"><p class="eyebrow dark">ENTRY &amp; PREPARATION</p><h3>Before you travel</h3><p>Confirm passport validity, visas, border rules, insurance, evacuation cover and access conditions using authorities relevant to your nationality and itinerary.</p><div class="travel-links"><a href="${links.entry}" target="_blank" rel="noopener">Entry requirements ↗</a><button type="button" class="primary" data-travel-safety="${esc(country)}">Prepare SOS contacts</button></div></section>`}
async function openCountry(country){selected=country;renderList();const ticket=++request;brief.innerHTML=`<div class="travel-brief-head"><p class="eyebrow">TRAVEL &amp; HEALTH</p><h2>${esc(country)}</h2><span class="travel-live-status"><i></i>Checking official advisory…</span></div><section class="travel-panel"><h3>Loading current travel advice…</h3><p>The offline country directory remains available while the official source is checked.</p></section>`;brief.scrollIntoView({behavior:'smooth',block:'start'});let data=null;try{const reference=await fetch('./assets/africa-country-reference.json').then(r=>r.ok?r.json():Promise.reject());data=reference.countries.find(x=>x.name===(aliases[country]||country))}catch{}const links=officialLinks(country,data);let advice=null;try{const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),7000),response=await fetch(`https://www.gov.uk/api/content/foreign-travel-advice/${slug(country)}`,{signal:controller.signal});clearTimeout(timer);if(!response.ok)throw new Error();advice=await response.json()}catch{}if(ticket!==request)return;const updated=advice?.public_updated_at?new Date(advice.public_updated_at).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'}):'';const summary=String(advice?.details?.change_description||'').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim();brief.innerHTML=`<div class="travel-brief-head"><p class="eyebrow">TRAVEL &amp; HEALTH</p><h2>${esc(country)}</h2><span class="travel-live-status ${advice?'live':''}"><i></i>${advice?'Official advisory loaded':'Live advisory unavailable'}</span></div><section class="travel-panel"><p class="eyebrow dark">TRAVEL ADVISORY</p><h3>Current official travel advice</h3>${advice?`<p>${esc(summary||'Open the official advisory for the complete current guidance.')}</p><p class="source-date">GOV.UK Foreign, Commonwealth &amp; Development Office · Updated ${esc(updated)} · Retrieved ${esc(new Date().toLocaleString())}</p>`:`<div class="travel-error"><strong>Could not load the live advisory.</strong><p>No cached advisory is being presented as current. Check connectivity or open the official source.</p><button type="button" data-travel-retry="${esc(country)}">Retry</button></div>`}<div class="travel-links"><a href="${links.gov}" target="_blank" rel="noopener">Open full advisory ↗</a></div></section>${staticPanels(country,data,links)}`}
search.addEventListener('input',renderList);clear.addEventListener('click',()=>{search.value='';renderList();search.focus()});list.addEventListener('click',e=>{const button=e.target.closest('[data-travel-country]');if(button)openCountry(button.dataset.travelCountry)});brief.addEventListener('click',e=>{const retry=e.target.closest('[data-travel-retry]');if(retry)openCountry(retry.dataset.travelRetry);const safety=e.target.closest('[data-travel-safety]');if(safety){document.getElementById('sosButton')?.click();const select=document.getElementById('safetyCountry');if(select){select.value=safety.dataset.travelSafety;select.dispatchEvent(new Event('change',{bubbles:true}))}}});
window.openTravelHealth=country=>{window.openPocketbookView?.('travelHealth');if(country)setTimeout(()=>openCountry(country),60)};renderList();
})();
